import { useEffect, useState } from "react";
import { LayoutDashboard, Package, Box, Tags, LogOut, Menu, Moon, Sun, Plus, Search, ArrowDownToLine, ArrowUpFromLine, RefreshCw, Trash2, RotateCcw, Wallet, Sparkles, BrainCircuit, CreditCard, Banknote, QrCode, X, CheckCircle2, ShieldCheck, Users, History, DatabaseBackup, KeyRound, LockKeyhole, UserRoundPlus, Cable, Printer, Barcode, Scale, ReceiptText, PlugZap, Wifi, CircleCheck, CircleAlert, ShoppingCart, Store, UsersRound, Receipt, WalletCards, BarChart3, PackageSearch, Boxes, Truck, SlidersHorizontal, Shield, ChevronRight, Bell } from "lucide-react";
import { api } from "./services/api";
const money=v=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(v||0);

function Login({onLogin}){const [u,setU]=useState("admin"),[p,setP]=useState("admin123"),[e,setE]=useState(""),[loading,setLoading]=useState(false);async function submit(x){x.preventDefault();setLoading(true);try{const d=await api.login(u,p);localStorage.setItem("mercadopro_token",d.access_token);onLogin(d.user)}catch(err){setE(err.message)}finally{setLoading(false)}}return <main className="login-page"><section className="login-card"><div className="brand-mark">M</div><h1>Mercado<span>Pro</span></h1><p className="muted">Gestão inteligente para o seu mercado</p><form onSubmit={submit}><label>Usuário<input value={u} onChange={e=>setU(e.target.value)}/></label><label>Senha<input type="password" value={p} onChange={e=>setP(e.target.value)}/></label>{e&&<div className="error">{e}</div>}<button className="primary full" disabled={loading}>{loading?"Entrando...":"Entrar no sistema"}</button></form><small className="demo-note">Ambiente de demonstração • admin / admin123</small></section></main>}

const navSections=[
 {label:"OPERAÇÃO",items:[["Dashboard",LayoutDashboard],["PDV",ShoppingCart],["Caixa",Store],["Clientes",UsersRound],["Vendas",Receipt]]},
 {label:"GESTÃO",items:[["Financeiro",WalletCards],["Relatórios",BarChart3],["Produtos",PackageSearch],["Estoque",Boxes],["Fornecedores",Truck],["Compras",ShoppingCart],["Cadastros",SlidersHorizontal]]},
 {label:"ADMINISTRAÇÃO",items:[["Segurança",Shield],["Integrações",Cable]]}
];
const menu=navSections.flatMap(s=>s.items.map(x=>x[0]));
function Reports(){
 const [tab,setTab]=useState("Visão geral"),[sales,setSales]=useState(null),[products,setProducts]=useState(null),[stock,setStock]=useState(null),[finance,setFinance]=useState(null),[purchases,setPurchases]=useState(null),[start,setStart]=useState(""),[end,setEnd]=useState("");
 async function load(){const [a,b,c,d,e]=await Promise.all([api.reportsSales(start,end),api.reportsProducts(start,end,10),api.reportsStock(),api.reportsFinance(),api.reportsPurchases(start,end)]);setSales(a);setProducts(b);setStock(c);setFinance(d);setPurchases(e)}
 useEffect(()=>{load()},[]);
 function csv(name,rows){const text=rows.map(r=>r.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(';')).join('\n');const blob=new Blob(["\ufeff"+text],{type:"text/csv;charset=utf-8"});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
 const kpi=sales?.summary||{};
 return <section className="page reports-page"><div className="page-title"><div><div className="ai-kicker"><Sparkles size={13}/> INSIGHTS OPERACIONAIS</div><h2>Relatórios</h2><p>Transforme os dados do MercadoPro em visão de operação.</p></div><button className="primary" onClick={load}><RefreshCw size={16}/> Atualizar dados</button></div>
 <div className="report-filters panel"><label>Período inicial<input type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label>Período final<input type="date" value={end} onChange={e=>setEnd(e.target.value)}/></label><button className="secondary" onClick={load}>Aplicar período</button></div>
 <div className="report-hero"><div><span className="micro-label">CENTRAL ANALÍTICA</span><strong>Seu mercado, em uma visão.</strong><p>Vendas, produtos, estoque, compras e financeiro reunidos em um único centro de análise.</p></div><div className="report-hero-orb"><BrainCircuit size={30}/></div></div>
 <div className="report-kpis"><div><span>Vendas no período</span><strong>{money(kpi.total)}</strong><small>{kpi.count||0} vendas</small></div><div><span>Ticket médio</span><strong>{money(kpi.average_ticket)}</strong><small>por venda</small></div><div><span>Estoque a custo</span><strong>{money(stock?.summary.stock_cost)}</strong><small>{stock?.summary.products||0} produtos ativos</small></div><div><span>Potencial em estoque</span><strong>{money(stock?.summary.potential_margin)}</strong><small>valor de venda − custo</small></div></div>
 <div className="report-tabs">{["Visão geral","Vendas","Produtos","Estoque","Financeiro","Compras"].map(x=><button className={tab===x?"active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>
 {tab==="Visão geral"&&<div className="report-grid"><div className="panel report-panel"><div className="panel-head"><div><h3>Ritmo de vendas</h3><p>Faturamento diário no período selecionado.</p></div></div><div className="chart-bars">{(sales?.daily||[]).map((x,i)=><div key={i}><span>{new Date(x.date).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}</span><i style={{height:`${Math.max(12,Math.min(150,(x.total/(Math.max(...(sales?.daily||[{total:1}]).map(y=>y.total))||1))*150))}px`}}></i><b>{money(x.total)}</b></div>)}</div></div><div className="panel report-panel"><div className="panel-head"><div><h3>Formas de pagamento</h3><p>Distribuição das vendas.</p></div></div><div className="payment-report">{(sales?.payments||[]).map(x=><div key={x.type}><div><span>{x.type}</span><b>{money(x.total)}</b></div><i style={{width:`${Math.min(100,(x.total/(kpi.total||1))*100)}%`}}/></div>)}</div></div></div>}
 {tab==="Vendas"&&<div className="panel table-wrap"><div className="panel-head"><div><h3>Resumo de vendas</h3><p>{sales?.period?.start?.slice(0,10)} até {sales?.period?.end?.slice(0,10)}</p></div><button className="secondary" onClick={()=>csv('mercadopro-vendas.csv',[["Data","Quantidade","Total"],...(sales?.daily||[]).map(x=>[x.date,x.count,x.total])])}>Exportar CSV</button></div><table><thead><tr><th>Data</th><th>Vendas</th><th>Faturamento</th></tr></thead><tbody>{(sales?.daily||[]).map(x=><tr key={x.date}><td>{new Date(x.date).toLocaleDateString('pt-BR')}</td><td>{x.count}</td><td>{money(x.total)}</td></tr>)}</tbody></table></div>}
 {tab==="Produtos"&&<div className="panel table-wrap"><div className="panel-head"><div><h3>Produtos mais vendidos</h3><p>Ordenados pelo faturamento gerado.</p></div><button className="secondary" onClick={()=>csv('mercadopro-produtos.csv',[["Código","Produto","Quantidade","Faturamento"],...(products?.items||[]).map(x=>[x.code,x.description,x.quantity,x.revenue])])}>Exportar CSV</button></div><table><thead><tr><th>Código</th><th>Produto</th><th>Quantidade</th><th>Faturamento</th></tr></thead><tbody>{(products?.items||[]).map(x=><tr key={x.product_id}><td>{x.code}</td><td><strong>{x.description}</strong></td><td>{x.quantity}</td><td>{money(x.revenue)}</td></tr>)}</tbody></table></div>}
 {tab==="Estoque"&&<div className="panel table-wrap"><div className="panel-head"><div><h3>Posição de estoque</h3><p>Custo, valor de venda e alertas.</p></div><button className="secondary" onClick={()=>csv('mercadopro-estoque.csv',[["Código","Produto","Estoque","Custo","Venda","Status"],...(stock?.items||[]).map(x=>[x.code,x.description,x.stock,x.cost,x.sale_price,x.status])])}>Exportar CSV</button></div><table><thead><tr><th>Código</th><th>Produto</th><th>Estoque</th><th>Custo</th><th>Venda</th><th>Status</th></tr></thead><tbody>{(stock?.items||[]).slice(0,100).map(x=><tr key={x.code}><td>{x.code}</td><td>{x.description}</td><td>{x.stock}</td><td>{money(x.cost)}</td><td>{money(x.sale_price)}</td><td><span className={`badge ${x.status==='NORMAL'?'green':x.status==='BAIXO'?'yellow':'red'}`}>{x.status}</span></td></tr>)}</tbody></table></div>}
 {tab==="Financeiro"&&<div className="report-grid"><div className="panel report-panel"><div className="panel-head"><div><h3>Contas em aberto</h3><p>Posição financeira atual.</p></div></div><div className="finance-report-cards"><span>A pagar<strong>{money(finance?.summary.pending_payables)}</strong></span><span>A receber<strong>{money(finance?.summary.pending_receivables)}</strong></span><span>Vencido a pagar<strong>{money(finance?.summary.overdue_payables)}</strong></span><span>Vencido a receber<strong>{money(finance?.summary.overdue_receivables)}</strong></span></div></div><div className="panel report-panel"><div className="panel-head"><div><h3>Atenção</h3><p>Lançamentos vencidos.</p></div></div>{(finance?.overdue||[]).slice(0,8).map(x=><div className="report-alert" key={x.id}><span>{x.type} · {x.due_date}</span><strong>{x.description}</strong><b>{money(x.amount)}</b></div>)}{!(finance?.overdue||[]).length&&<div className="empty">Nenhum lançamento vencido.</div>}</div></div>}
 {tab==="Compras"&&<div className="panel table-wrap"><div className="panel-head"><div><h3>Compras realizadas</h3><p>Total por fornecedor e período.</p></div><button className="secondary" onClick={()=>csv('mercadopro-compras.csv',[["Número","Data","Fornecedor","Total"],...(purchases?.items||[]).map(x=>[x.number,x.date,x.supplier,x.total])])}>Exportar CSV</button></div><div className="report-mini-grid">{(purchases?.by_supplier||[]).slice(0,4).map(x=><div key={x.supplier}><span>{x.supplier}</span><strong>{money(x.total)}</strong></div>)}</div><table><thead><tr><th>Número</th><th>Data</th><th>Fornecedor</th><th>Total</th></tr></thead><tbody>{(purchases?.items||[]).map(x=><tr key={x.number}><td>{x.number}</td><td>{new Date(x.date).toLocaleDateString('pt-BR')}</td><td>{x.supplier}</td><td>{money(x.total)}</td></tr>)}</tbody></table></div>}
 </section>
}

function ProductForm({item,onClose,onSaved}){const [cats,setCats]=useState([]),[brands,setBrands]=useState([]),[units,setUnits]=useState([]);const [f,setF]=useState(item||{internal_code:"",barcode:"",description:"",short_description:"",category_id:"",brand_id:"",unit_id:"",cost_price:0,sale_price:0,min_stock:0,max_stock:0,supplier_name:"",location:"",expiry_date:"",active:true});const [err,setErr]=useState("");useEffect(()=>{Promise.all([api.categories(),api.brands(),api.units()]).then(([a,b,c])=>{setCats(a);setBrands(b);setUnits(c)})},[]);function set(k,v){setF(x=>({...x,[k]:v}))}async function save(e){e.preventDefault();setErr("");try{await api.saveProduct(f,item?.id);onSaved()}catch(x){setErr(x.message)}}return <div className="modal-bg"><form className="modal" onSubmit={save}><div className="modal-head"><div><h3>{item?"Editar produto":"Novo produto"}</h3><p>Cadastro comercial e controle de estoque.</p></div><button type="button" className="icon-btn" onClick={onClose}>×</button></div><div className="form-grid"><label>Código interno*<input value={f.internal_code} onChange={e=>set("internal_code",e.target.value)}/></label><label>Código de barras<input value={f.barcode||""} onChange={e=>set("barcode",e.target.value)}/></label><label className="wide">Descrição*<input value={f.description} onChange={e=>set("description",e.target.value)}/></label><label>Categoria*<select value={f.category_id} onChange={e=>set("category_id",Number(e.target.value))}><option value="">Selecione</option>{cats.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>Marca<select value={f.brand_id||""} onChange={e=>set("brand_id",e.target.value?Number(e.target.value):null)}><option value="">Selecione</option>{brands.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>Unidade*<select value={f.unit_id} onChange={e=>set("unit_id",Number(e.target.value))}><option value="">Selecione</option>{units.map(x=><option value={x.id} key={x.id}>{x.code} — {x.name}</option>)}</select></label><label>Custo<input type="number" step="0.01" min="0" value={f.cost_price} onChange={e=>set("cost_price",e.target.value)}/></label><label>Preço de venda<input type="number" step="0.01" min="0" value={f.sale_price} onChange={e=>set("sale_price",e.target.value)}/></label><label>Estoque mínimo<input type="number" step="0.001" min="0" value={f.min_stock} onChange={e=>set("min_stock",e.target.value)}/></label><label>Estoque máximo<input type="number" step="0.001" min="0" value={f.max_stock} onChange={e=>set("max_stock",e.target.value)}/></label><label>Fornecedor<input value={f.supplier_name||""} onChange={e=>set("supplier_name",e.target.value)}/></label><label>Localização<input value={f.location||""} onChange={e=>set("location",e.target.value)}/></label><label>Validade<input type="date" value={f.expiry_date?String(f.expiry_date).slice(0,10):""} onChange={e=>set("expiry_date",e.target.value||null)}/></label></div>{err&&<div className="error">{err}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary"><Plus size={16}/>Salvar produto</button></div></form></div>}

function Products(){const [data,setData]=useState({items:[],total:0,pages:0}),[q,setQ]=useState(""),[modal,setModal]=useState(null);async function load(){setData(await api.products(q))}useEffect(()=>{load()},[]);return <section className="page"><div className="page-title"><div><p className="eyebrow">CADASTRO</p><h2>Produtos</h2><p>Gerencie produtos, preços e estoque mínimo.</p></div><button className="primary" onClick={()=>setModal({})}><Plus size={17}/> Novo produto</button></div><div className="panel toolbar"><div className="search"><Search size={17}/><input placeholder="Buscar código, código de barras ou descrição..." value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==="Enter"&&load()}/></div><button className="secondary" onClick={load}>Pesquisar</button></div><div className="panel table-wrap"><table><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th></th></tr></thead><tbody>{data.items.map(p=><tr key={p.id}><td>{p.internal_code}</td><td><strong>{p.description}</strong><small>{p.barcode||"Sem código de barras"}</small></td><td>{p.category||"—"}</td><td>{money(p.sale_price)}</td><td>{p.current_stock} <small>mín. {p.min_stock}</small></td><td><span className={`badge ${p.current_stock<=0?"red":p.current_stock<=p.min_stock?"yellow":"green"}`}>{p.current_stock<=0?"Sem estoque":p.current_stock<=p.min_stock?"Baixo":"Normal"}</span></td><td><button className="link-btn" onClick={()=>setModal(p)}>Editar</button></td></tr>)}</tbody></table>{!data.items.length&&<div className="empty">Nenhum produto encontrado.</div>}</div>{modal&&<ProductForm item={modal.id?modal:null} onClose={()=>setModal(null)} onSaved={()=>{setModal(null);load()}}/>}</section>}

function Stock(){const [sum,setSum]=useState(null),[products,setProducts]=useState({items:[]}),[selected,setSelected]=useState(""),[qty,setQty]=useState(""),[type,setType]=useState("ENTRY"),[reason,setReason]=useState("");async function load(){setSum(await api.inventorySummary());setProducts(await api.products("", "", "", ""))}useEffect(()=>{load()},[]);async function move(){try{await api.movement({product_id:Number(selected),quantity:qty,movement_type:type,reason});setQty("");setReason("");await load();alert("Movimentação registrada com sucesso.")}catch(e){alert(e.message)}}return <section className="page"><div className="page-title"><div><p className="eyebrow">OPERAÇÃO</p><h2>Estoque</h2><p>Controle real de entradas, saídas e ajustes.</p></div></div><div className="cards"><Metric title="Produtos" value={sum?.total_products}/><Metric title="Sem estoque" value={sum?.out_of_stock}/><Metric title="Estoque baixo" value={sum?.low_stock}/><Metric title="Próximos da validade" value={sum?.near_expiry}/></div><div className="grid-two"><div className="panel"><div className="panel-head"><div><h3>Nova movimentação</h3><p>Atualiza o estoque e registra histórico.</p></div></div><div className="form-grid"><label className="wide">Produto<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Selecione</option>{products.items.map(p=><option value={p.id} key={p.id}>{p.internal_code} — {p.description}</option>)}</select></label><label>Tipo<select value={type} onChange={e=>setType(e.target.value)}><option value="ENTRY">Entrada</option><option value="EXIT">Saída</option><option value="ADJUSTMENT">Ajuste</option><option value="LOSS">Perda</option><option value="RETURN">Devolução</option></select></label><label>Quantidade<input type="number" min="0.001" step="0.001" value={qty} onChange={e=>setQty(e.target.value)}/></label><label className="wide">Motivo<input value={reason} onChange={e=>setReason(e.target.value)}/></label></div><button className="primary" disabled={!selected||!qty} onClick={move}>Registrar movimentação</button></div><div className="panel"><div className="panel-head"><div><h3>Status</h3><p>Resumo atual do estoque.</p></div></div><div className="attention"><div className="attention-row"><div className="alert-icon blue"><Package size={18}/></div><div><strong>Cadastro de produtos</strong><span>{sum?.active_products||0} produtos ativos</span></div></div><div className="attention-row"><div className="alert-icon red"><ArrowDownToLine size={18}/></div><div><strong>Sem estoque</strong><span>{sum?.out_of_stock||0} produtos</span></div></div><div className="attention-row"><div className="alert-icon yellow"><RefreshCw size={18}/></div><div><strong>Estoque baixo</strong><span>{sum?.low_stock||0} produtos</span></div></div></div></div></div></section>}
function Metric({title,value,icon,sub}){return <div className="metric"><div className="metric-top"><span>{title}</span><div className="metric-icon">{icon||<Box size={18}/>}</div></div><h3>{value??"—"}</h3><small>{sub||""}</small></div>}
function Dashboard(){const [d,setD]=useState(null),[loading,setLoading]=useState(true);async function load(){setLoading(true);try{setD(await api.dashboard())}finally{setLoading(false)}}useEffect(()=>{load()},[]);const m=d?.sales_today||0,month=d?.sales_month||0,max=Math.max(...(d?.latest_sales||[]).map(x=>Number(x.total)||0),1);return <section className="page dashboard-page"><div className="dashboard-head"><div><div className="eyebrow">VISÃO OPERACIONAL</div><h2>Visão geral da loja</h2><p>Um resumo claro do que está acontecendo no MercadoPro.</p></div><div className="dashboard-head-actions"><div className="live-status"><i/> Operação conectada</div><button className="secondary" onClick={load}><RefreshCw size={15}/> Atualizar</button></div></div><div className="dashboard-hero"><div><span className="micro-label">MERCADOPRO INTELLIGENCE</span><strong>O desempenho da sua loja, sem ruído.</strong><p>Indicadores de venda, caixa e estoque organizados para você tomar decisões rapidamente.</p></div><div className="hero-stat"><span>Faturamento do mês</span><strong>{money(month)}</strong><small>{d?.sales_count||0} vendas registradas hoje</small></div></div><div className="dashboard-kpis"><Metric title="Vendas hoje" value={money(m)} icon={<Receipt/>} sub={`${d?.sales_count||0} operações`}/><Metric title="Ticket médio" value={money(d?.average_ticket)} icon={<WalletCards/>} sub="por venda"/><Metric title="Produtos vendidos" value={d?.products_sold||0} icon={<Package/>} sub="hoje"/><Metric title="Caixa aberto" value={money(d?.cash)} icon={<Store/>} sub={d?.cash?"saldo atual":"nenhum caixa aberto"}/></div><div className="dashboard-main-grid"><div className="panel dashboard-chart-panel"><div className="panel-head"><div><h3>Últimas vendas</h3><p>Movimentação recente do ponto de venda.</p></div><button className="link-btn" onClick={()=>window.dispatchEvent(new CustomEvent('mercadopro:navigate',{detail:'Vendas'}))}>Ver vendas</button></div>{loading?<div className="dashboard-loading"><span/><span/><span/></div>:d?.latest_sales?.length?<div className="sales-bars">{d.latest_sales.map(x=><div className="sale-bar" key={x.id}><div className="sale-bar-value">{money(x.total)}</div><div className="sale-bar-track"><i style={{height:`${Math.max(18,(Number(x.total)/max)*100)}%`}}/></div><strong>{x.number}</strong><small>{new Date(x.sale_date).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>)}</div>:<div className="empty">As vendas realizadas aparecerão aqui.</div>}</div><div className="dashboard-side-stack"><div className="panel intelligence-panel"><div className="panel-head"><div><span className="ai-kicker">CENTRAL DE ATENÇÃO</span><h3>Pontos que merecem atenção</h3></div><CircleAlert size={18}/></div><div className="attention-list"><div><span className="attention-number red">{d?.out_of_stock||0}</span><div><strong>Produtos sem estoque</strong><small>Precisam de reposição.</small></div></div><div><span className="attention-number amber">{d?.low_stock||0}</span><div><strong>Estoque baixo</strong><small>Abaixo do mínimo configurado.</small></div></div><div><span className="attention-number blue">{d?.near_expiry||0}</span><div><strong>Próximos da validade</strong><small>Itens dentro dos próximos 30 dias.</small></div></div></div></div><div className="panel stock-summary"><div className="panel-head"><div><h3>Estoque</h3><p>Saúde atual do catálogo.</p></div><PackageSearch size={18}/></div><div className="stock-summary-grid"><div><strong>{d?.active_products||0}</strong><span>Produtos ativos</span></div><div><strong>{d?.total_products||0}</strong><span>Total cadastrado</span></div></div></div></div></div></section>}
function Catalog(){const [cats,setCats]=useState([]),[brands,setBrands]=useState([]),[units,setUnits]=useState([]),[name,setName]=useState("");async function load(){const [a,b,c]=await Promise.all([api.categories(),api.brands(),api.units()]);setCats(a);setBrands(b);setUnits(c)}useEffect(()=>{load()},[]);async function add(type){if(!name.trim())return;try{if(type==="category")await api.createCategory(name);if(type==="brand")await api.createBrand(name);setName("");load()}catch(e){alert(e.message)}}return <section className="page"><div className="page-title"><div><p className="eyebrow">CADASTROS AUXILIARES</p><h2>Categorias, marcas e unidades</h2><p>Base para o cadastro de produtos.</p></div></div><div className="catalog-grid">{[["Categorias",cats,"category"],["Marcas",brands,"brand"]].map(([t,items,type])=><div className="panel" key={t}><div className="panel-head"><h3>{t}</h3></div><div className="inline-add"><input placeholder={`Nova ${type==="category"?"categoria":"marca"}`} value={name} onChange={e=>setName(e.target.value)}/><button className="primary" onClick={()=>add(type)}>Adicionar</button></div>{items.map(x=><div className="list-row" key={x.id}><span>{x.name}</span><span className="badge green">Ativo</span></div>)}</div>)}<div className="panel"><div className="panel-head"><h3>Unidades</h3></div>{units.map(x=><div className="list-row" key={x.id}><strong>{x.code}</strong><span>{x.name}</span></div>)}</div></div></section>}


