 useEffect(()=>{api.products().then(setProducts);api.customers().then(setCustomers)},[]);
 const add=(p)=>setItems(old=>{const f=old.find(i=>i.product_id===p.id);if(f)return old.map(i=>i.product_id===p.id?{...i,quantity:Number(i.quantity)+1}:i);return [...old,{product_id:p.id,description:p.description,barcode:p.barcode,quantity:1,unit_price:Number(p.sale_price),stock:Number(p.current_stock)}]});
